test("protected path probe", async () => {
  const home = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "zz-home-")));
  process.env.HOME = home;
  const config = path.join(home, ".config", "nexus"); fs.mkdirSync(config, { recursive: true, mode: 0o700 });
  const hooks = path.join(config, "hooks.json"), store = path.join(config, "extension_trust.json");
  fs.writeFileSync(hooks, "ORIG", { mode: 0o600 }); fs.writeFileSync(store, "ORIG", { mode: 0o600 });
  const stateDir = fs.mkdtempSync(path.join(os.tmpdir(), "zz-state-"));
  const results: string[] = [];
  for (const ws of [config, home, path.join(home, ".config"), path.dirname(home)]) {
    const agent = hookAgent({ repo: ws, stateDir, mode: "auto", fullAccess: true, notices: [] });
    const rel = (p: string) => path.relative(ws, p) || ".";
    const targets = (f: string) => [rel(f), "./" + rel(f), f, path.join(ws, "x", "..", rel(f)), rel(f).replace(/hooks/, "HOOKS").replace(/extension/, "Extension")];
