    fs.mkdirSync(config, { recursive: true, mode: 0o700 }); fs.writeFileSync(hooks, "ORIG", { mode: 0o600 }); fs.writeFileSync(store, "ORIG", { mode: 0o600 });
  }
  console.log(results.join("\n"));
});
EOF
